import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Search Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/search-syntax.md","filePath":"user-guide/search-syntax.md","lastUpdated":1783870824000}'),i={name:"user-guide/search-syntax.md"};function r(n,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="search-syntax" tabindex="-1">Search Syntax <a class="header-anchor" href="#search-syntax" aria-label="Permalink to &quot;Search Syntax&quot;">​</a></h1><p>SwiftList&#39;s query box supports more than plain typing. Every operator below can be combined with plain fuzzy terms in the same query.</p><h2 id="fuzzy-matching-default" tabindex="-1">Fuzzy matching (default) <a class="header-anchor" href="#fuzzy-matching-default" aria-label="Permalink to &quot;Fuzzy matching (default)&quot;">​</a></h2><p>Type any part of a name and SwiftList finds it as long as the characters occur in order, anywhere in the file/folder name — you don&#39;t need to type a contiguous substring:</p><table tabindex="0"><thead><tr><th>You type</th><th>Matches</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>SwiftList.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><h2 id="multiple-words" tabindex="-1">Multiple words <a class="header-anchor" href="#multiple-words" aria-label="Permalink to &quot;Multiple words&quot;">​</a></h2><p>Separate words with a space. Each word narrows the result set further — it does <strong>not</strong> require the words to appear in the same order you typed them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p>matches <code>final-Q3-report.docx</code> just as well as <code>Q3-report-final.docx</code>.</p><h2 id="case-sensitivity" tabindex="-1">Case sensitivity <a class="header-anchor" href="#case-sensitivity" aria-label="Permalink to &quot;Case sensitivity&quot;">​</a></h2><ul><li>An <strong>all-lowercase</strong> query is case-insensitive: <code>myfile</code> matches <code>MyFile</code>, <code>MYFILE</code>, etc.</li><li>A query with <strong>any uppercase letter</strong> becomes case-sensitive for that term: <code>MyFile</code> only matches <code>MyFile</code>, not <code>myfile</code>.</li></ul><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefix/Suffix</th><th>Example</th><th>Effect</th></tr></thead><tbody><tr><td><em>(none)</em></td><td><code>report</code></td><td>Fuzzy match anywhere in the name (default).</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>Exclude</strong> results that match <code>temp</code>.</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td><strong>Exact</strong> substring match instead of fuzzy.</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>Exact match anchored to word boundaries (won&#39;t match inside a larger word).</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>Prefix</strong> match — the name must start with <code>IMG</code>.</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>Suffix</strong> match — the name must end with <code>.pdf</code>.</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>OR</strong> — match either side of the pipe.</td></tr></tbody></table><p>You can mix these freely, e.g. <code>^IMG !.png$ 2024</code> finds files starting with <code>IMG</code>, from 2024, that are <em>not</em> PNGs.</p><h2 id="targeting-a-drive" tabindex="-1">Targeting a drive <a class="header-anchor" href="#targeting-a-drive" aria-label="Permalink to &quot;Targeting a drive&quot;">​</a></h2><p>Start the query with a drive letter followed by a colon to restrict results to that drive, then continue typing your search as normal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>searches only on the <code>D:</code> drive.</p><h2 id="path-mode" tabindex="-1">Path mode <a class="header-anchor" href="#path-mode" aria-label="Permalink to &quot;Path mode&quot;">​</a></h2><p>If your query contains a path separator (<code>\\</code> or <code>/</code>), SwiftList switches to path mode and matches against full paths instead of just names — useful for jumping straight to a known folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\SwiftList</span></span></code></pre></div><p>A trailing separator (<code>D:\\Projects\\</code>) searches the <em>contents</em> of that exact folder.</p><h2 id="filtering-by-folder-name" tabindex="-1">Filtering by folder name <a class="header-anchor" href="#filtering-by-folder-name" aria-label="Permalink to &quot;Filtering by folder name&quot;">​</a></h2><p>Add a trailing <code>::&lt;text&gt;</code> to a query to additionally require that the result&#39;s own name or one of its ancestor folders matches <code>&lt;text&gt;</code> (fuzzy, same matching — including pinyin — as everywhere else):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1080 ::wallpapers</span></span></code></pre></div><p>finds files with <code>1080</code> in the name that live somewhere under a folder matching <code>wallpapers</code>, without needing to know or type the exact path. Combine multiple filters with a comma: <code>report ::2024,:final</code>.</p><h2 id="bypassing-exclusion-rules-for-one-search" tabindex="-1">Bypassing exclusion rules for one search <a class="header-anchor" href="#bypassing-exclusion-rules-for-one-search" aria-label="Permalink to &quot;Bypassing exclusion rules for one search&quot;">​</a></h2><p>Start a query with <code>*</code> to search past your own <a href="./settings/index-drives.html#exclusion-rules">exclusion rules</a> — <code>ExcludedPaths</code>, ignored globs, and ignored regexes — just for that search, without changing your settings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>The <code>*</code> itself is stripped before matching, so it&#39;s never treated as part of the search text. This only reveals results that are already indexed; a folder that was <em>never</em> indexed in the first place (an excluded folder on a network or WSL drive) still won&#39;t appear. Hidden/system files stay filtered either way — this only affects your own exclusion-rule configuration.</p><h2 id="chinese-filenames-pinyin-aliasing" tabindex="-1">Chinese filenames: pinyin aliasing <a class="header-anchor" href="#chinese-filenames-pinyin-aliasing" aria-label="Permalink to &quot;Chinese filenames: pinyin aliasing&quot;">​</a></h2><p>Filenames containing Chinese characters are automatically searchable by pinyin, with no setup required:</p><ul><li><strong>Full pinyin</strong>: typing <code>chongqing</code> matches a file named <code>重庆</code>.</li><li><strong>Initials</strong>: typing <code>cq</code> also matches <code>重庆</code> (first letter of each syllable).</li><li><strong>Polyphonic characters</strong> (characters with more than one valid pronunciation) generate aliases for each common reading, so whichever pronunciation you think of is likely to match.</li></ul><p>This is handled by a bundled alias plugin — see <strong>Settings → Plugins</strong> if you ever want to check it&#39;s enabled.</p><h2 id="favorites-not-custom-aliases" tabindex="-1">Favorites, not custom aliases <a class="header-anchor" href="#favorites-not-custom-aliases" aria-label="Permalink to &quot;Favorites, not custom aliases&quot;">​</a></h2><p>SwiftList does not have a general-purpose &quot;define your own alias/macro&quot; system. The closest equivalent is <a href="./settings/favorites.html">Favorites</a>: pin a folder, file, or URL under a custom display name, and it becomes searchable by that name (shown with a ★ marker in results). If what you actually want is a custom keyword that launches a program, see <a href="./instant-answers.html#custom-commands">Custom Commands</a> instead.</p>',36)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
